import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';

/** A person in a pool, or another pool (memberPool its name, personId ''), with a share percent (two decimals). A
 *  retired member's share counts as 0.00 toward the total. Their cut is their part of the pool's pot, two decimals
 *  ('' when the pool is unbalanced or there is no pot). A pool that is a member of no pool has the sheet's pot; one
 *  that is a member of another has its cut there as its pot. */
export type PoolMember = {
  personId: string;
  memberPool: string;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
};

/** A pool on the sheet: its members in the order added, their total share, and balanced when it is exactly 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

// Under the people's key: a change to a person (a retirement, a new name) reads the pools again too.
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'] as const;

/** The pools on the sheet, by name. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`)).pools,
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useOnce } from '../../query/useOnce';
import { postJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';
import { useUser } from '../session/session';
import { usePeople } from '../people/people';
import { poolsKey, usePools } from './pools';
import type { Pool } from './pools';

// The sheet's pools: a name entry and an add button, each pool listed below with its total share, whether
// it is balanced (the shares total exactly 100.00; a retired member's counts as 0.00) and its members, each
// with their share and their cut of the pot (blank when the pool is unbalanced or there is no pot). A member is added from the pool's row: a person,
// or another pool (pool:<name>), and a share. A member pool's pot is its cut in the pool above. The server decides
// what is refused — a taken or blank name, a person already in the pool, a share not more than 0.00 and at most
// 100.00 with two decimals, a pool already in a pool, one containing itself through any chain, or a chain more than
// three deep — and the form shows its error.
function Pools({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const pools = usePools(sheetId);
  const [name, setName] = useState('');
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const add = useMutation({
    mutationFn: (body: { name: string }) =>
      postJson<Pool>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, body, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
    onError: () => setError('That pool could not be added.'),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    once((done) => add.mutate({ name }, { onSettled: done }));
  };

  return (
    <section data-testid="pools">
      <h2>Pools</h2>
      <form onSubmit={submit}>
        <label>
          Name{' '}
          <input
            data-testid="pool-form-name"
            value={name}
            onChange={(e) => {
              setName(e.target.value);
              setError('');
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {error && (
          <p role="alert" data-testid="pool-form-error">
            {error}
          </p>
        )}
      </form>
      <ul data-testid="pool-list">
        {(pools.data ?? []).map((p) => (
          <PoolRow key={p.name} sheetId={sheetId} pool={p} />
        ))}
      </ul>
    </section>
  );
}

function PoolRow({ sheetId, pool }: { sheetId: string; pool: Pool }) {
  const queryClient = useQueryClient();
  const people = usePeople(sheetId);
  const pools = usePools(sheetId);
  // A person's id, or pool:<name> for a member pool.
  const [member, setMember] = useState('');
  const [share, setShare] = useState('');
  const [error, setError] = useState('');
  const [user] = useUser();

  const once = useOnce();
  const add = useMutation({
    mutationFn: (body: { pool: string; personId: string; memberPool: string; share: string }) =>
      postJson(`/api/sheets/${encodeURIComponent(sheetId)}/pool-members`, body, user),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
    onError: () => setError(`That member could not be added to ${pool.name}.`),
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const memberPool = member.startsWith('pool:') ? member.slice('pool:'.length) : '';
    const personId = memberPool ? '' : member;
    once((done) => add.mutate({ pool: pool.name, personId, memberPool, share }, { onSettled: done }));
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share">{pool.totalShare}</span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.memberPool ? `pool-${m.memberPool}` : m.personId}
            data-testid={`pool-member-${pool.name}-${m.memberPool ? `pool-${m.memberPool}` : m.personId}`}
          >
            {m.name}
            {m.retired ? ' (retired)' : ''}: <span data-testid="pool-share">{m.share}</span>%, cut{' '}
            <span data-testid="pool-cut">{m.cut}</span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select
          data-testid="pool-member-select"
          value={member}
          onChange={(e) => {
            setMember(e.target.value);
            setError('');
          }}
        >
          <option value="">Person…</option>
          {(people.data ?? []).map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
          {(pools.data ?? [])
            .filter((p) => p.name !== pool.name)
            .map((p) => (
              <option key={`pool:${p.name}`} value={`pool:${p.name}`}>
                {`pool:${p.name}`}
              </option>
            ))}
        </select>{' '}
        <input
          data-testid="pool-member-share"
          placeholder="share %"
          value={share}
          onChange={(e) => {
            setShare(e.target.value);
            setError('');
          }}
        />{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
        {error && (
          <p role="alert" data-testid="pool-error">
            {error}
          </p>
        )}
      </form>
    </li>
  );
}

export const contribution = SheetBody.fill({ order: -5.3, Component: Pools });
import { SheetBody } from '../../slots/defs/sheetBody';
import { liveHolds, usePeople } from '../people/people';
import { useSheetToday } from '../sheet/sheet';
import { sumAmounts, useClaims } from './claims';

// The sheet's claimed-total: everyone's claims added up.
function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useClaims(sheetId);
  const today = useSheetToday(sheetId);
  const holds = new Map((usePeople(sheetId).data ?? []).map((p) => [p.id, liveHolds(p, today)]));
  return (
    <p>
      Claimed in all: <strong data-testid="rollup-claimed-total">{sumAmounts(claims.data ?? [], (id) => holds.get(id) ?? [], today)}</strong>
    </p>
  );
}

export const contribution = SheetBody.fill({ order: 10, Component: ClaimedTotal });

